#include <map>
#include <string>
#include <vector>

class Inventory
{
public:
    bool addNew(const std::string& item, int count) { return false; }
    bool set(const std::string& item, int count) { return false; }
    int countOf(const std::string& item) const { return 0; }
    bool take(const std::string& item, int n) { return false; }
    std::size_t removeEmpty() { return 0; }
    std::size_t size() const { return 0; }
    std::vector<std::string> items() const { return {}; }

private:
    std::map<std::string, int> stock_;
};

solution.solution.cpp:
#include <map>
#include <string>
#include <vector>

class Inventory
{
public:
    bool addNew(const std::string& item, int count) { return stock_.try_emplace(item, count).second; }
    bool set(const std::string& item, int count) { return stock_.insert_or_assign(item, count).second; }

    int countOf(const std::string& item) const
    {
        const auto it{ stock_.find(item) };
        return it == stock_.end() ? 0 : it->second;
    }

    bool take(const std::string& item, int n)
    {
        const auto it{ stock_.find(item) };
        if (it == stock_.end() || it->second < n) return false;
        it->second -= n;
        return true;
    }

    std::size_t removeEmpty()
    {
        return std::erase_if(stock_, [](const auto& entry) { return entry.second == 0; });
    }

    std::size_t size() const { return stock_.size(); }

    std::vector<std::string> items() const
    {
        std::vector<std::string> names;
        for (const auto& [name, count] : stock_) names.push_back(name);
        return names;
    }

private:
    std::map<std::string, int> stock_;
};

unitTests:
TEST("adding never overwrites") {
    Inventory inv;
    CHECK(inv.addNew("rope", 3));
    CHECK(!inv.addNew("rope", 99));
    CHECK_EQ(inv.countOf("rope"), 3);
    CHECK_EQ(inv.size(), 1u);
}
TEST("setting always writes") {
    Inventory inv;
    CHECK(inv.set("torch", 2));
    CHECK(!inv.set("torch", 5));
    CHECK_EQ(inv.countOf("torch"), 5);
    inv.addNew("map", 1);
    CHECK(!inv.set("map", 0));
    CHECK_EQ(inv.countOf("map"), 0);
}
TEST("looking up never adds") {
    Inventory inv;
    inv.addNew("key", 1);
    CHECK_EQ(inv.countOf("ghost"), 0);
    CHECK_EQ(inv.size(), 1u);
}
TEST("taking is all or nothing") {
    Inventory inv;
    inv.addNew("arrow", 10);
    CHECK(inv.take("arrow", 4));
    CHECK_EQ(inv.countOf("arrow"), 6);
    CHECK(!inv.take("arrow", 7));
    CHECK_EQ(inv.countOf("arrow"), 6);
    CHECK(inv.take("arrow", 6));
    CHECK_EQ(inv.countOf("arrow"), 0);
    CHECK_EQ(inv.size(), 1u);
    CHECK(!inv.take("bolt", 1));
    CHECK_EQ(inv.size(), 1u);
}
TEST("removing empty items") {
    Inventory inv;
    inv.addNew("a", 0); inv.addNew("b", 2); inv.addNew("c", 0); inv.addNew("d", 1);
    CHECK_EQ(inv.removeEmpty(), 2u);
    CHECK(inv.items() == (std::vector<std::string>{ "b", "d" }));
    CHECK_EQ(inv.removeEmpty(), 0u);
}
TEST("names in order") {
    Inventory inv;
    inv.set("zinc", 1); inv.set("apple", 1); inv.set("Mango", 1);
    CHECK(inv.items() == (std::vector<std::string>{ "Mango", "apple", "zinc" }));
}

